void trie_collect_words_helper(struct trie *trie, char prefix[], unsigned prefix_len, char **buffer, int *buffer_index, int max_words)
{
    if (NULL == trie || (*buffer_index) >= max_words) {
        return;
    }

    if (true == trie->end_of_word) {
        // Allocate and copy word
        buffer[*buffer_index] = malloc(prefix_len + 1);
        if (NULL != buffer[*buffer_index]) {
            memcpy(buffer[*buffer_index], prefix, prefix_len);
            buffer[*buffer_index][prefix_len] = '\0';
            (*buffer_index)++;
        }
    }

    for (int i = 0; i < 26 && (*buffer_index) < max_words; i++) {
        struct trie *child = &trie->children[i];
        if (child == NULL) {
            continue;
        }
        prefix[prefix_len] = i + 'a';
        trie_collect_words_helper(child, prefix, prefix_len + 1,
                                   buffer, buffer_index, max_words);
    }
}

